function closestTri(p,a,b,c){let ab=vsub(b,a),ac=vsub(c,a),ap=vsub(p,a),d1=dot(ab,ap),d2=dot(ac,ap);if(d1<=0&&d2<=0)return a;let bp=vsub(p,b),d3=dot(ab,bp),d4=dot(ac,bp);if(d3>=0&&d4<=d3)return b;let vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return vadd(a,vmul(ab,d1/(d1-d3)));let cp=vsub(p,c),d5=dot(ab,cp),d6=dot(ac,cp);if(d6>=0&&d5<=d6)return c;let vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return vadd(a,vmul(ac,d2/(d2-d6)));let va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0)return vadd(b,vmul(vsub(c,b),(d4-d3)/((d4-d3)+(d5-d6))));let den=1/(va+vb+vc),v=vb*den,w=vc*den;return vadd(a,vadd(vmul(ab,v),vmul(ac,w)))}
