function patchSeatContact(){let A=global.LUCID_RIDER_CONTACTS_V12851;if(!A||A.__v12853SeatPatch)return false;let base=A.evaluate.bind(A);A.evaluate=function(){let E=base();if(rt.pos&&E?.states?.pelvis){let ext=global.LUCID_CORNER_BALANCE_V12861?.seatContactSample?.(),m=ext?{gapM:ext.gapM,closestM:ext.seatPointM}:seatPatchDistance(effPoint('pelvis')),s=E.states.pelvis,c=A.affordances?.affordances?.['seat.topSupport']?.capture||{};s.gapM=m.gapM;s.closestM=m.closestM;s.state=m.gapM<=(c.engageGapM||.008)?'ENGAGED':m.gapM<=(c.candidateGapM||.035)?'CANDIDATE':'READY';s.geometryAuthority=ext?'DYNAMIC_SEAT_SUPPORT_MANIFOLD':'FULL_ACTUAL_SEAT_TOP_PATCH';if(ext){s.supportRegion=ext.region;s.supportState=ext.state}}return E};A.summary=function(){let E=A.evaluate(),v=Object.values(E.states||{});return{total:v.length,engaged:v.filter(s=>s.state==='ENGAGED'||s.state==='LOADED').length,ready:v.filter(s=>s.state==='READY'||s.state==='CANDIDATE').length}};A.__v12853SeatPatch=true;return true}
