function gaze(){if(!rt.pose)return null;let o=pAt(rt.pose.P,TI.Head),dir=norm(mv(gAt(rt.pose.G,TI.Head),DATA.forward)),up=norm(mv(gAt(rt.pose.G,TI.Head),DATA.up||[0,0,1])),snap=null;try{snap=global.DUCATI_V5_API?.snapshot?.()}catch(_e){}let q=snap?.body?.quaternion||[0,0,0,1],wd=norm(qrot4(q,dir)),wu=norm(qrot4(q,up)),heading=qrot4(q,[0,1,0]);heading=norm([heading[0],heading[1],0]);let herr=Math.acos(clamp(dot(wd,heading),-1,1))*180/Math.PI,upErr=Math.acos(clamp(dot(wu,[0,0,1]),-1,1))*180/Math.PI;return{originBodyLocalM:o,directionBodyLocal:dir,directionWorld:wd,headUpWorld:wu,desiredHorizonDirectionWorld:heading,horizonDirectionErrorDeg:herr,headUpTiltFromWorldDeg:upErr,eyeJointAuthority:'UNAVAILABLE',mode:'HEAD_NECK_HORIZON_AIM_NO_EYEBALL_DOF'}}
