function updatePose(){let t=performance.now(),cp=compile(),s=skinPose(cp);rt.pose=s;rt.pos=s.pos;rt.nor=normals(rt.pos);rt.mass=massUpdate(rt.pos);gpuUpdate();rt.updates++;rt.lastUpdateMs=performance.now()-t;controlSurfaceState();return s}
function applyBike(){if(!controls.linkBike)return;let A=global.DUCATI_V5_API,st=global.DUCATI_ADVANCED_POWERTRAIN?.states?.free?.command||{};if(!A?.setPowertrainControls)return;let q={...st,mode:st.mode||'ENGINE',throttle:controls.throttle,clutch:1-controls.clutch,frontBrakeBar:controls.frontBrake*70,rearBrakeBar:controls.rearBrake*40};A.setPowertrainControls(q,'FREE_ROAD')}
function syncBike(){if(!controls.followBike)return false;let dom=global.DUCATI_V5_API?.domain?.()==='FREE_ROAD'?'free':'dyno',st=global.DUCATI_ADVANCED_POWERTRAIN?.states?.[dom]?.command;if(!st)return false;controls.throttle=clamp(+st.throttle||0,0,1);controls.clutch=clamp(1-(st.clutch??1),0,1);controls.frontBrake=clamp((+st.frontBrakeBar||0)/70,0,1);controls.rearBrake=clamp((+st.rearBrakeBar||0)/40,0,1);let g=+st.gear||1;if(rt.lastGear!==null&&g!==rt.lastGear){controls.shift=Math.sign(g-rt.lastGear);rt.shiftUntil=performance.now()+260}rt.lastGear=g;return true}
function setControls(q={},opt={}){Object.assign(controls,q);for(let k of ['throttle','clutch','frontBrake','rearBrake'])controls[k]=clamp(+controls[k]||0,0,1);for(let k of ['seatForeAft','posture','shift'])controls[k]=clamp(+controls[k]||0,-1,1);controls.lookYawDeg=clamp(+controls.lookYawDeg||0,-45,45);controls.lookPitchDeg=clamp(+controls.lookPitchDeg||0,-20,20);if(opt.manual)controls.followBike=false;updatePose();if(opt.drive!==false)applyBike();refresh();return snapshot()}
